import React, { useEffect, useState } from 'react';
import './cookie-banner.css';

const COOKIE_KEY = 'jsk_cookie_consent';

type ConsentState = 'accepted' | 'rejected' | null;

const CookieBanner: React.FC = () => {
  const [consent, setConsent] = useState<ConsentState>(null);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const saved = window.localStorage.getItem(COOKIE_KEY) as ConsentState;
    setConsent(saved);
    if (!saved) setIsVisible(true);

    const onUpdate = () => {
      const updated = window.localStorage.getItem(COOKIE_KEY) as ConsentState;
      setConsent(updated);
      setIsVisible(false);
    };
    window.addEventListener('cookie-consent-updated', onUpdate);
    return () => window.removeEventListener('cookie-consent-updated', onUpdate);
  }, []);

  const handleChoice = (value: ConsentState) => {
    if (typeof window === 'undefined') return;
    setConsent(value);
    window.localStorage.setItem(COOKIE_KEY, value || 'rejected');
    setIsVisible(false);
  };

  if (!isVisible) return null;

  return (
    <div className="cookie-banner">
      <div className="cookie-banner-content">
        <div>
          <p className="cookie-banner-title">We use cookies to improve your experience.</p>
          <p className="cookie-banner-text">
            By clicking accept, you agree to our use of analytics and site functionality cookies. You can reject them or manage your preferences on the cookie page.
          </p>
        </div>
        <div className="cookie-banner-actions">
          <button className="cookie-btn reject" onClick={() => handleChoice('rejected')}>Reject</button>
          <a href="/cookie-policy" className="cookie-btn manage">Manage cookies</a>
          <button className="cookie-btn accept" onClick={() => handleChoice('accepted')}>Accept</button>
        </div>
      </div>
    </div>
  );
};

export default CookieBanner;
